        </h1>
        <Suspense>
          <AgeGroupTabs />
        </Suspense>
        <div className="mt-4 space-y-3">
          {games.length === 0 ? (
            <p className="text-gray-500">Ігор не знайдено.</p>
          ) : (
            games.map((g) => <GameCard key={g.id} game={g} />)
          )}
        </div>
      </div>
    );
  } catch (error) {
    console.error("SchedulePage error:", error);
    throw error;
  }
}

