            </button>
            <button
              onClick={handleNavSave}
              disabled={pending}
              className="px-6 py-2 rounded-lg font-bold text-white text-sm disabled:opacity-60"
              style={{ backgroundColor: "#f97316" }}
            >
              Зберегти навігацію
            </button>
          </div>
        </section>
      </div>
    );
  }
);

export default TextsTab;

