        )}
      </div>
    </header>
  );
}

export default function Header(props: HeaderProps) {
  return (
    <Suspense fallback={
      <header style={{ backgroundColor: props.navyColor, width: "100%", height: `${props.headerHeight}px` }} className="text-white shadow-lg" />
    }>
      <HeaderInner {...props} />
    </Suspense>
  );
}

