      <button
        onClick={() => setAuthOpen(true)}
        style={{
          padding: "6px 16px",
          borderRadius: "8px",
          fontSize: "26px",
          fontWeight: 700,
          backgroundColor: orange,
          color: "white",
          border: "none",
