          background: rgba(15, 23, 42, 1);
        }

        ::-webkit-scrollbar-thumb {
          background: rgba(255, 77, 0, 0.5);
          border-radius: 4px;
        }

        ::-webkit-scrollbar-thumb:hover {
          background: rgba(255, 77, 0, 0.8);
        }
      `}</style>
    </div>
  );
}

